function resolveDataPath()
    if _G.YargiDataPath and _G.YargiDataPath ~= "" then
        return _G.YargiDataPath
    end
    local candidates = {
        "/storage/emulated/0/Download",
        "/storage/emulated/0",
        "/sdcard/Download",
        "/sdcard",
    }
    for _, p in ipairs(candidates) do
        local ok, writable = pcall(function()
            local f = io.open(p .. "/.yargi_probe", "w")
            if f then f:close() os.remove(p .. "/.yargi_probe") return true end
            return false
        end)
        if ok and writable then
            _G.YargiDataPath = p
            return p
        end
    end
    _G.YargiDataPath = "/storage/emulated/0/Download"
    return _G.YargiDataPath
end

local PACKAGE_LIST = {
    "com.tencent.ig", "com.pubg.krmobile", "com.vng.pubgmobile",
    "com.rekoo.pubgm", "com.rekoo.pubgmobile", "com.pubg.imobile",
}

local function buildConfigPaths()
    local paths = {}
    local base = resolveDataPath()
    paths[#paths + 1] = base .. "/yargi_config.ini"
    paths[#paths + 1] = base .. "/YargiConfig.ini"
    paths[#paths + 1] = base .. "/config.ini"
    for _, pkg in ipairs(PACKAGE_LIST) do
        paths[#paths + 1] = "/storage/emulated/0/Android/data/" .. pkg .. "/files/yargi_config.ini"
        paths[#paths + 1] = "/storage/emulated/0/Android/data/" .. pkg .. "/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Config/Android/yargi_config.ini"
    end
    return paths
end

function resolveKillCounterPath()
    return resolveDataPath() .. "/yargi_kills.lua"
end

local CONFIG_PATHS = nil

function Yargi.getConfigPaths()
    if not CONFIG_PATHS then CONFIG_PATHS = buildConfigPaths() end
    return CONFIG_PATHS
end

