function Yargi.parseEmbeddedSkinDb()
    if Yargi._parsedSkinDb then return Yargi._parsedSkinDb end
    if Yargi._SKIN_DB_RAW then
        local compile = loadstring or load
        local fn, err = compile(Yargi._SKIN_DB_RAW)
        if fn then
            local ok, res = pcall(fn)
            if ok and type(res) == "table" then
                Yargi._parsedSkinDb = res
                return res
            end
        else
        end
    end
    return nil
end

function Yargi.loadStaticSkinDatabase()
    if Yargi.staticSkinLoaded then return true end
    local data = Yargi.parseEmbeddedSkinDb()
    if not data then data = EMBEDDED_SKIN_DB end
    if not data then
        return false
    end

    local outfitKeys = {
        "Suit", "Bag", "Helmet", "Gloves", "Pants", "Parachute", "Glider",
        "Pet", "PetDress", "Head", "Hair", "Hat", "Face", "Armor",
        "HandEffect", "LastKill", "FinalKill", "VehicleEffect",
    }
    for _, key in ipairs(outfitKeys) do
        if data[key] and type(data[key]) == "table" then
            _G.OutfitSkins[key] = data[key]
        end
    end

    if data.LobbyTheme then _G.LobbyThemeSkins = data.LobbyTheme end
    if data.skinIdMappings then _G.skinIdMappings = data.skinIdMappings end
    if data.GrenadeSkins then
        for baseId, list in pairs(data.GrenadeSkins) do
            _G.skinIdMappings[tonumber(baseId) or baseId] = list
        end
    end
    if data.VehskinIdMappings then _G.VehskinIdMappings = data.VehskinIdMappings end
    if data.allRegisterIds then Yargi._allRegisterIds = data.allRegisterIds end

    Yargi.injectFeaturedSkins()
    Yargi.refreshOutfitMaps()
    Yargi.staticSkinLoaded = true
    Yargi.allSkinsRegistered = false
    return true
end

