end

function Yargi.batchRegisterTick(batchSize)
    batchSize = batchSize or 150
    if not Yargi._registerQueue then return end
    local q, i = Yargi._registerQueue, Yargi._registerQueueIdx or 1
    local n = #q
    local endIdx = math.min(i + batchSize - 1, n)
    for j = i, endIdx do
        local resID = q[j]
        if resID and resID ~= 0 then Yargi.registerFakeResID(resID) end
    end
    Yargi._registerQueueIdx = endIdx + 1
    if Yargi._registerQueueIdx > n then
        Yargi._registerQueue = nil
    end
end

function Yargi.ensureAllSkinsRegistered()
    if Yargi.allSkinsRegistered then return end
    if not Yargi.staticSkinLoaded then Yargi.loadStaticSkinDatabase() end
    local count = 0
    local regOutfitKeys = {
        "Suit", "Bag", "Helmet", "Gloves", "Pants", "Parachute", "Glider",
        "Pet", "PetDress", "Head", "Hair", "Hat", "Face", "Armor",
        "HandEffect", "LastKill", "FinalKill", "VehicleEffect",
    }
    for _, key in ipairs(regOutfitKeys) do
        local list = _G.OutfitSkins[key] or {}
        for _, resID in ipairs(list) do
            if resID and resID ~= 0 then
                Yargi.registerFakeResID(resID)
                count = count + 1
            end
        end
    end
    for _, skins in pairs(_G.skinIdMappings) do
        for _, resID in ipairs(skins) do
            Yargi.registerFakeResID(resID)
            count = count + 1
        end
    end
    for _, skins in pairs(_G.VehskinIdMappings) do
        for _, resID in ipairs(skins) do
            Yargi.registerFakeResID(resID)
            count = count + 1
        end
    end
    if _G.LobbyThemeSkins then
        for _, resID in ipairs(_G.LobbyThemeSkins) do
            Yargi.registerFakeResID(resID)
            count = count + 1
        end
    end
    Yargi.registerEquippedGlobals()
    Yargi.queueBulkRegisterIds()
    Yargi.allSkinsRegistered = true
end

