function Yargi.isFakeIns(insID)
    insID = tonumber(insID)
    return insID and insID >= Yargi.FAKE_INS_BASE
end

function Yargi.isFakeRes(resID)
    return resID and Yargi.fakeResSet[tonumber(resID)] ~= nil
end

function Yargi.inferWardrobeFields(resID)
    resID = tonumber(resID)
    if not resID then return nil end
    if resID >= 1501001000 and resID < 1501016000 then
        return { mainTabType = 1, itemSubType = ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.Upgrade_Backpack or 501 }
    elseif resID >= 1502001000 and resID < 1502016000 then
        return { mainTabType = 1, itemSubType = 502 }
    elseif (resID >= 402000 and resID < 403000) or (resID >= 452000 and resID < 453000) then
        return { mainTabType = 1, itemSubType = ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.Gloves or 402 }
    elseif resID >= 1410000 and resID < 1420000 then
        return { mainTabType = 1, itemSubType = ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.Pants_Slot or 405 }
    elseif resID >= 1400000 and resID < 1415000 then
        return { mainTabType = 1, itemSubType = 403 }
    elseif resID >= 703000 and resID < 704000 then
        return { mainTabType = 4, itemSubType = 703 }
    elseif resID >= 4151000 and resID < 4152000 then
        return { mainTabType = 4, itemSubType = 4151 }
    end
    return nil
end

function Yargi.ensureItemFields(item)
    if not item or item.bConfigLoaded then return item end
    pcall(function()
        local CDataTable = require("client.slua.config.ClientConfig.data_mgr")
        local cfg = CDataTable.GetTableData("Item", item.resID)
        if cfg then
            item.itemType = cfg.ItemType
            item.itemSubType = cfg.ItemSubType
            item.mainTabType = cfg.WardrobeMainTab
            item.subTabType = cfg.WardrobeTab
            item.itemQuality = cfg.ItemQuality
        else
            local inferred = Yargi.inferWardrobeFields(item.resID)
            if inferred then
                item.mainTabType = inferred.mainTabType
                item.itemSubType = inferred.itemSubType
                item.itemType = ENUM_ITEM_TYPE and ENUM_ITEM_TYPE.Extra or 0
                item.itemQuality = 7
            end
        end
        item.bConfigLoaded = true
    end)
    return item
end

function Yargi.buildFakeDepotItem(resID)
    resID = tonumber(resID)
    if not resID or resID == 0 then return nil end
    local insID = Yargi.FAKE_INS_BASE + resID
    local item = {
        insID = insID,
        resID = resID,
        expireTS = 0,
        count = 1,
        lock_cnt = 0,
        colorID = 0,
        patternID = 0,
        validHours = 0,
        isNew = false,
        bConfigLoaded = false
    }
    return Yargi.ensureItemFields(item)
end

function Yargi.registerFakeResID(resID)
    resID = tonumber(resID)
    if not resID or resID == 0 then return end
    if Yargi.fakeResSet[resID] then
        _G.SkinLoadedCache[resID] = true
        return
    end
    local item = Yargi.buildFakeDepotItem(resID)
    if not item then return end
    Yargi.fakeDepot[item.insID] = item
    Yargi.fakeResSet[resID] = item.insID
    _G.SkinLoadedCache[resID] = true
end

function Yargi.registerAllFakeItems()
    Yargi.ensureAllSkinsRegistered()
end

